import{_ as t,c as n,o as s,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const j=JSON.parse('{"title":"四库全书序","description":"周易经传集解 - 四库全书序","frontmatter":{"title":"四库全书序","description":"周易经传集解 - 四库全书序"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/001.md","filePath":"zh/classics/jingchuan-jijie/001.md"}'),l={name:"zh/classics/jingchuan-jijie/001.md"};function r(c,a,o,p,d,u){return s(),n("div",null,[...a[0]||(a[0]=[e("p",null,"钦定四库全书经部一",-1),e("h1",{id:"四库全书序",tabindex:"-1"},[i("四库全书序 "),e("a",{class:"header-anchor",href:"#四库全书序","aria-label":"Permalink to “四库全书序”"},"​")],-1),e("p",null,"易类提要",-1),e("p",null,"臣等谨案：",-1),e("p",null,"周易经传集解三十六卷，宋林栗撰。栗字黄中，福清人。绍兴十二年进士，官至兵部侍郎。与朱子论易及西铭不合，遂上疏论朱子。时太常博士叶适、侍御史胡晋臣皆助朱子劾栗，因罢知泉州，乂移明州。卒谥简肃。事迹具宋史本传。是书淳熙十二年四月尝进于朝，首列进书表、贴黄、敕谕各一道，栗自序一篇。贴黄称本名周易爻象序杂指解，后以未能该举彖词、击词、文言说卦，乃改今名。王应麟玉海称具书经传三十二卷、系词上下二卷、文言说卦序杂本文共一卷，河图洛书八卦九畴大衍总会图六十四卦立成图大衍揲蓍解共一卷，与今本合。当时与朱子所争者，今不可考。朱子语类中惟载论繋词一条，谓栗以太极生两仪，包四象，四象包八卦，与圣人所谓生者意思不同，其余则无所排斥。朱彝尊经义考引董真卿之言，谓其说每卦必兼互体、约象、覆卦为太泥。时杨敬仲有易论，黄中有易解，或曰：「黄中文字可毁。」朱子曰：「却是杨敬仲文字可毁。」是朱子并不欲废其书。考陈振孙书录解题曰：「其与朱侍讲有违言，以论易不合。」今以事理推之，于时朱子负盛名，骎骎向用，而栗之登第在朱子前七年，既以前辈自居，又朱子方除兵部郎中，而栗为兵部侍郎，正其所属，词色相轧，两不肯下，遂互激而成讦奏。盖其衅始于论易，而其故不全由于论易，故振孙云然。后人以朱子之故，遂废栗书，似非朱子之意矣。经义考又曰：「福清林黄中、金华唐与政，皆博通经学，而一纠朱子，一为朱子所纠，其所著经说，学者遂置而不问，与政之书无复存者。黄中虽有易解，而流传未广，恐后泯没。然当黄中既殁，勉齐黄氏为文祭之，其略曰：嗟哉我公，受天劲气，为时直臣。玩羲经之爻象，究笔削于获麟。至其立朝正色，苟咈吾意，虽当世大儒，或见排斥；苟异吾趋，虽前贤笃论，亦不乐于因循。规公之过，而公之近仁者，抑可见矣。论者固不以一𤯝而掩其大醇也。勉斋为文公高弟，而好恶之公、推许之至若是，然则黄中之易，其可不传钞乎？」持论颇为平允。昔刘安世与伊川程子各为一代伟人，其元城语录、尽言集亦不以尝劾程子而废。耿南仲媚敌误国，易祓依附权奸，其所撰易解，今亦并行。栗虽不得比安世，视南仲与祓则有间矣。故仍录其书，而并存「彝尊」之论焉。乾隆四十六年九月恭校上。",-1),e("p",null,"总纂官臣纪呁、臣陆锡熊、臣孙士毅，总校官臣陆费墀。",-1)])])}const m=t(l,[["render",r]]);export{j as __pageData,m as default};
